"""通用 UI 工具：窗口图标、弹窗、相对父窗口的 messagebox 等"""
import base64
import os
import tempfile
import tkinter as tk
from tkinter import messagebox
from typing import Callable, Optional

import customtkinter as ctk

from src.utils.styles import Colors

# 程序图标（base64 编码的 .ico）。打包后是单个 exe，没有独立的图标文件，所以内嵌在代码中
ICON_BASE64 = ""

_icon_file: Optional[str] = None


def _read_bytes(path: str) -> Optional[bytes]:
    try:
        with open(path, "rb") as f:
            return f.read()
    except OSError:
        return None


def _icon_path() -> Optional[str]:
    """把内嵌图标写到固定的临时文件（已存在且内容相同则直接复用），返回其路径。

    iconbitmap 只接受文件路径；用固定文件名，避免每次启动都在临时目录留下一个新文件。
    """
    global _icon_file
    if _icon_file is not None:
        return _icon_file

    data = base64.b64decode(ICON_BASE64)
    path = os.path.join(tempfile.gettempdir(), "dcsm_icon.ico")
    if _read_bytes(path) != data:
        # 先写临时文件再替换，避免同时启动的多个实例读到半个文件
        tmp = None
        try:
            fd, tmp = tempfile.mkstemp(suffix=".ico", dir=os.path.dirname(path))
            with os.fdopen(fd, "wb") as f:
                f.write(data)
            os.replace(tmp, path)
        except OSError:
            if tmp and os.path.exists(tmp):
                os.remove(tmp)
            return None
    _icon_file = path
    return path


def set_window_icon(window) -> None:
    """设置窗口图标（非 Windows 平台不支持 .ico 时静默忽略）"""
    try:
        path = _icon_path()
        if path:
            window.iconbitmap(path)
    except (tk.TclError, OSError):
        pass


def _show_relative(func, parent, title, message, **options):
    """以 parent 为父窗口弹出 messagebox，使其显示在该窗口上方；parent 不可用时退回默认位置"""
    try:
        parent.update_idletasks()
        return func(title, message, parent=parent, **options)
    except (tk.TclError, AttributeError):
        return func(title, message, **options)


def showinfo_relative(parent, title, message):
    return _show_relative(messagebox.showinfo, parent, title, message)


def showwarning_relative(parent, title, message):
    return _show_relative(messagebox.showwarning, parent, title, message)


def showerror_relative(parent, title, message):
    return _show_relative(messagebox.showerror, parent, title, message)


def askyesno_relative(parent, title, message, icon="question"):
    return _show_relative(messagebox.askyesno, parent, title, message, icon=icon)


def restore_and_activate_window(window) -> bool:
    """把窗口从最小化恢复并提到最前；窗口不存在时返回 False"""
    if window is None:
        return False
    try:
        if not window.winfo_exists():
            return False
        window.deiconify()
        window.lift()
        window.focus_force()
        window.update_idletasks()
        return True
    except tk.TclError:
        return False


def widget_alive(widget: Optional[tk.Misc]) -> bool:
    """控件（或窗口）是否还存在；已销毁或为 None 时返回 False"""
    try:
        return widget is not None and bool(widget.winfo_exists())
    except tk.TclError:
        return False


def center_window(window: tk.Misc) -> None:
    """把窗口移到屏幕中央（窗口尺寸需已确定）"""
    window.update_idletasks()
    width, height = window.winfo_width(), window.winfo_height()
    if width <= 0 or height <= 0:
        return
    x = max(0, (window.winfo_screenwidth() - width) // 2)
    y = max(0, (window.winfo_screenheight() - height) // 2)
    window.geometry(f"+{x}+{y}")


def grab_when_visible(dialog: tk.Toplevel, retries: int = 12, delay_ms: int = 30) -> None:
    """让对话框成为模态（grab_set）；窗口还没显示出来时 grab_set 会报错，所以稍后重试"""
    def try_grab(remaining: int) -> None:
        if remaining <= 0 or not widget_alive(dialog):
            return
        try:
            dialog.grab_set()
        except tk.TclError:
            dialog.after(delay_ms, lambda: try_grab(remaining - 1))

    try:
        dialog.deiconify()
        dialog.update_idletasks()
    except tk.TclError:
        pass
    try_grab(retries)


def create_dialog(parent: tk.Misc, title: str, geometry: Optional[str] = None, *,
                  modal: bool = True, use_ctk: bool = False) -> tk.Toplevel:
    """创建一个附属于 parent 的弹窗（所有弹窗都用这个函数创建）

    use_ctk=False 时是白底的 tk.Toplevel；use_ctk=True 时是 CTkToplevel（可以放 CTk 控件）。
    modal=True 时弹窗打开期间不能操作其他窗口。
    """
    dialog = ctk.CTkToplevel(parent) if use_ctk else tk.Toplevel(parent)
    if not use_ctk:
        dialog.configure(bg=Colors.WHITE)
    dialog.title(title)
    if geometry:
        dialog.geometry(geometry)
    dialog.transient(parent)
    # 窗口显示后 Tk / CTk 会把图标重置成默认的，所以显示前后多设几次
    set_window_icon(dialog)
    dialog.after(50, lambda: set_window_icon(dialog))
    dialog.after(200, lambda: set_window_icon(dialog))
    if modal:
        grab_when_visible(dialog)
    return dialog


def bind_mousewheel(widget: tk.Misc, on_scroll: Callable[[int], None]) -> None:
    """把 widget 及其所有子控件的滚轮事件转给 on_scroll(方向)，方向 -1 向上、1 向下

    Tk 的滚轮事件只发给鼠标下方的控件，所以要递归绑定到每个子控件上。
    Windows/macOS 用 <MouseWheel>，Linux 用 <Button-4>/<Button-5>。
    """
    def handler(event: tk.Event) -> str:
        if getattr(event, "num", None) == 4 or getattr(event, "delta", 0) > 0:
            on_scroll(-1)
        else:
            on_scroll(1)
        return "break"

    def bind(w: tk.Misc) -> None:
        for sequence in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            w.bind(sequence, handler)
        for child in w.winfo_children():
            bind(child)

    bind(widget)
